    # dp[i] = maximum sum of increasing subsequence ending at index i
    dp = [0] * n
    for i in range(n):
        dp[i] = a[i]

    # Build dp for indices 0..index
    for i in range(index + 1):
        for j in range(i):
            if a[j] < a[i] and dp[i] < dp[j] + a[i]:
                dp[i] = dp[j] + a[i]

    # Now find the maximum dp[i] for i in [0..index] where a[i] < a[k]
    max_sum = a[k]  # in case no prefix element is smaller than a[k]
    for i in range(index + 1):
        if a[i] < a[k] and dp[i] + a[k] > max_sum:
            max_sum = dp[i] + a[k]

    return max_sum

